type suspiciousKeyFinding struct {
	Agent string `json:"agent"`
	Path string `json:"path"`
	Action string `json:"action"`
	Key string `json:"key"`
	Nested bool `json:"nested"`
}

// suspiciousKeyChars: doc-notation punctuation that appears in schema
// documentation ('category?', 'glob*', 'key: value') and never in a key an
// action reads — bugs_open/134, where '?' leaked from a seed comment into two
// live key names that then never resolved.
const suspiciousKeyChars = "?* :"

func findSuspiciousKeys(agents []liveAgent) []suspiciousKeyFinding {
	findings := []suspiciousKeyFinding{}
	for _, agent := range agents {
		validation.WalkSteps(agent.Workflow, func(path string, step models.Step, nested bool) {
			for key := range step.Config {
				if strings.ContainsAny(key, suspiciousKeyChars) {
					findings = append(findings, suspiciousKeyFinding{Agent: agent.Type, Path: path, Action: step.Action, Key: key, Nested: nested})
				}
			}
		})
	}
	sort.Slice(...)
	return findings
}
// emitSuspiciousKeys: same stdin decode + refuse-empty + exit-1-on-findings
// shape as emitUnregisteredActions; wired as `--suspicious-keys` in main().

func TestFindSuspiciousKeys(t *testing.T) {
	agents := []liveAgent{{Type: "a1", Workflow: fixtureWithKeys(map[string]string{"category?": "x", "limit": "y"}, nestedKeys("opt*"))}}
	got := findSuspiciousKeys(agents)
	// expect exactly {category?, top} and {opt*, nested}; a clean fixture returns none
}
